//! Cross-renderer fixture contract: generated by the actual Rust cell helpers.
use super::*;
use ratatui::style::Modifier;
use serde_json::{Value, json};

fn rect(r: Rect) -> [u16; 4] {
    [r.x, r.y, r.width, r.height]
}
fn hex(c: Color) -> String {
    match c {
        Color::Rgb(r, g, b) => format!("#{r:02x}{g:02x}{b:02x}"),
        Color::Reset => "reset".into(),
        _ => panic!("fixture uses RGB only"),
    }
}
fn cells(buf: &Buffer) -> Value {
    json!(
        (0..buf.area.height)
            .map(|y| {
                let mut covered = false;
                (0..buf.area.width)
                    .map(|x| {
                        let cell = &buf[(x, y)];
                        let ch = if covered { "" } else { cell.symbol() };
                        covered = !covered && crate::ui::width(cell.symbol()) > 1;
                        let mods: Vec<_> = [
                            (Modifier::BOLD, "bold"),
                            (Modifier::ITALIC, "italic"),
                            (Modifier::UNDERLINED, "underline"),
                        ]
                        .into_iter()
                        .filter_map(|(flag, name)| cell.modifier.contains(flag).then_some(name))
                        .collect();
                        json!({"ch":ch,"fg":hex(cell.fg),"bg":hex(cell.bg),"mods":mods})
                    })
                    .collect::<Vec<_>>()
            })
            .collect::<Vec<_>>()
    )
}
fn plain() -> Buffer {
    let mut buf = Buffer::empty(Rect::new(0, 0, 20, 10));
    for cell in &mut buf.content {
        cell.set_symbol(".")
            .set_fg(Color::Rgb(11, 22, 33))
            .set_bg(Color::Rgb(4, 5, 6))
            .set_style(
                ratatui::style::Style::new().add_modifier(Modifier::BOLD | Modifier::ITALIC),
            );
    }
    buf
}
fn mark(border: Border<'_>) -> Value {
    json!({"area":rect(border.area),"title":border.top_title.map(rect),"keep":border.keep.iter().copied().map(rect).collect::<Vec<_>>()})
}
#[test]
fn rust_interaction_reference_matches_committed_cells() {
    let mut cases = vec![];
    let area = Rect::new(2, 3, 10, 5);
    let viewport = Rect::new(2, 2, 10, 6);
    let mut expanded = plain();
    let mut compact = plain();
    for (y, text) in ["界e\u{301}CHILD1", "CHILD2", "CHILD3", "TAIL-A", "TAIL-B"]
        .iter()
        .enumerate()
    {
        expanded.set_string(
            area.x,
            area.y + y as u16,
            text,
            ratatui::style::Style::new(),
        );
    }
    for (y, text) in ["TAIL-A", "TAIL-B", "TAIL-C", "TAIL-D", "TAIL-E"]
        .iter()
        .enumerate()
    {
        compact.set_string(
            area.x,
            area.y + y as u16,
            text,
            ratatui::style::Style::new(),
        );
    }
    let retain = |buf: &Buffer| area.positions().map(|p| buf[p].clone()).collect::<Vec<_>>();
    let expanded_cells = retain(&expanded);
    let compact_cells = retain(&compact);
    for open in [true, false] {
        let (before, after) = if open {
            (&compact, &expanded)
        } else {
            (&expanded, &compact)
        };
        let border = Border {
            area: viewport,
            top_title: None,
            keep: &[],
        };
        let frames: Vec<_> = [0, 40, 80, 120, 159, 160]
            .into_iter()
            .map(|ms| {
                let mut buf = after.clone();
                compose_fold(
                    &mut buf,
                    viewport,
                    FoldRows {
                        area,
                        expanded: &expanded_cells,
                        compact: &compact_cells,
                        descendants: 3,
                        direction: if open {
                            FoldDirection::Open
                        } else {
                            FoldDirection::Close
                        },
                    },
                    ms,
                );
                json!({"ms":ms,"rows":cells(&buf)})
            })
            .collect();
        cases.push(json!({"name":if open {"wide-open"}else{"wide-close"},"kind":"fold","width":20,"height":10,"before":cells(before),"after":cells(after),"before_mark":mark(border),"after_mark":mark(border),"area":rect(area),"descendants":3,"open":open,"frames":frames}));
    }
    let stops = [
        (1, 3, 5),
        (11, 13, 15),
        (21, 23, 25),
        (31, 33, 35),
        (41, 43, 45),
        (51, 53, 55),
        (61, 63, 65),
    ];
    let band = FocusBand(stops);
    let keep = [Rect::new(16, 3, 1, 4)];
    let border = Border {
        area: Rect::new(1, 1, 16, 8),
        top_title: Some(Rect::new(3, 1, 5, 1)),
        keep: &keep,
    };
    let before = plain();
    let mut after = plain();
    for (i, p) in perimeter(border.area).enumerate() {
        after[p].set_fg(Color::Rgb(80 + (i % 100) as u8, 90, 100));
    }
    for drain in [false, true] {
        let frames: Vec<_> = [0, 75, 150, 225, 299, 300]
            .into_iter()
            .map(|ms| {
                let mut buf = after.clone();
                let prior = border_foregrounds(&before, border).unwrap();
                if drain {
                    focus_drain(&mut buf, border, border, &prior, ms);
                } else {
                    focus_lap(&mut buf, border, border, &prior, band, ms);
                }
                json!({"ms":ms,"rows":cells(&buf)})
            })
            .collect();
        cases.push(json!({"name":if drain {"protected-drain"}else{"custom-protected-lap"},"kind":if drain {"focus_drain"}else{"focus_lap"},"width":20,"height":10,"before":cells(&before),"after":cells(&after),"before_mark":mark(border),"after_mark":mark(border),"stops":stops.map(|(r,g,b)|hex(Color::Rgb(r,g,b))),"frames":frames}));
    }
    let value = json!({"cases":cases});
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../ink/test/motion/fixtures/ratatui-interaction.json");
    if std::env::var_os("RADAR_INTERACTION_REF").is_some() {
        std::fs::write(&path, serde_json::to_string(&value).unwrap() + "\n").unwrap();
    }
    let committed: Value = serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap();
    assert_eq!(committed, value);
}
